let channel=null,serverScope='',sessionNotice='',observedRelease=null;const sessionEvents=[];
function sessionEvent(kind,detail={}){sessionEvents.push({at:new Date().toISOString(),kind,...detail});if(sessionEvents.length>30)sessionEvents.shift();}
function authReportVisible(){if($('authReport'))$('authReport').hidden=false;}
function staleSession(e){return e?.code==='SESSION_CHANGED';}
function sessionChanged(message){sessionEvent('identity_change',{role:session?.user?.role||''});showLogin();sessionNotice=message;$('authError').textContent=message;authReportVisible();}
function bindSessionChannel(health){
 observedRelease={version:health.release?.version,build:health.release?.build,instance:health.instance};serverScope=String(health.instance||'')+':'+location.port;
 try{channel?.close();channel=new BroadcastChannel('ronix-session:'+serverScope);channel.onmessage=async e=>{
  if(e.data?.scope!==serverScope||!session||busy)return;
  const expected=session,epoch=roleEpoch;
  try{const next=await api('/api/session');if(epoch!==roleEpoch||session!==expected)return;
   if(next.user.id!==expected.user.id||next.user.role!==expected.user.role){sessionChanged(T('تم تغيير الحساب في نافذة أخرى من نفس النسخة. استخدم تلك النافذة أو سجّل الدخول هنا بالحساب المطلوب.','Account changed in another tab of this installation. Use that tab or sign in here.'));return;}
   session=next; // same account: rotate CSRF safely; do not wipe edits or log out.
  }catch(error){if(!staleSession(error)&&error.status!==401)$('connection').textContent=T('تعذر تحديث حالة الاتصال. بيانات الشاشة لم تُمسح.','Session refresh unavailable. Current view retained.');}
 };}catch(_){channel=null;}
}
