function financial(){return ['Owner','Accountant','Project Manager'].includes(session?.user.role)}function owner(){return ['Owner','Project Manager'].includes(session?.user.role)}function role(){return session?.user.role}function myPM(p){return p.pm===session?.user.id&&role()==='Project Manager'}function canPlan(p){return (owner()||myPM(p))&&!p.operationalClosed&&!p.finalTechnicalApproved&&p.operation?.canPlan!==false}function name(id){return ws?.users.find(u=>u.id===id)?.name||id||'—'}
