async function api(url,opt={}){
 const started=performance.now(),epoch=roleEpoch;const headers={...(opt.headers||{})};if(opt.method&&opt.method!=='GET'){headers['Content-Type']='application/json';if(session)headers['X-Ronix-CSRF']=session.csrf}
 const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...opt,headers});let data;try{data=await r.json()}catch(_){data={message:'تعذر قراءة رد الخادم'}}
 if(epoch!==roleEpoch){sessionEvent('old_response_ignored',{path:String(url).split('?')[0],status:r.status});const e=Error('تغير الدور؛ تم تجاهل الرد السابق');e.code='SESSION_CHANGED';throw e}
 timings.push({operation:(opt.method||'GET')+' '+url.split('?')[0],ms:performance.now()-started,status:r.status,at:new Date().toISOString()});if(timings.length>80)timings.shift();
 if(!r.ok){const e=Error(data.message||r.statusText);e.code=data.error;e.status=r.status;if(r.status===401&&session){sessionEvent('reauthentication_required',{path:String(url).split('?')[0],status:r.status,code:data.error||'',build:data.build||'',role:session.user.role});session=null;showLogin();$('authError').textContent=T('انتهت جلسة هذه النسخة أو تغيّر الحساب. أعد الدخول.','This installation session expired or the account changed. Sign in again.');authReportVisible();}throw e}return data;
}
