 timeFilter={state:'all',project:'',employee:'',from:'',to:''};recordFilter={kind:'project',state:'active',search:''};taskFilter={state:'active',project:'',priority:'',search:'',engineer:''};focusedTask='';projectListState='active';projectListSearch='';projectAudience32='mine';busy=true;roleEpoch++;clearInterval(poll);$('view').replaceChildren();$('navigation').replaceChildren();
