 modal(T('بدء التشغيل من عرض سعر أو عقد','Start from quotation or contract'),`<div class="notice">${T('اربط المسودة الموجودة أو أنشئ مشروعًا جديدًا. المرجع المرتبط بمشروع يستخدم نفس المشروع دون مضاعفته.','Use an existing draft or create a new project. An already linked source keeps its existing project.')}</div><div class="form-grid">${select('sourceKey',T('مرجع التشغيل المعتمد','Approved source'),[['',T('اختر المرجع','Select source')],...sources.map(c=>[c.key,`${c.type==='quote'?'عرض':'عقد'} · ${c.number} · ${c.client} · ${c.projectName} — ${c.reason}`])],preselect,'required')}${select('targetProject',T('المشروع المستهدف','Target project'),[['',T('اختر المرجع أولًا','Choose source first')]],targetProject)}${select('pmId',T('مهندس المشروعات','Project manager'),options(['Project Manager']),'pm')}${select('checkerId',T('المراجع — للتنفيذ الداخلي','Checker — internal work'),[['','تشغيل خارجي بالكامل — دون تشيكر'],...options(['Checker'])])}${field('deadline',T('التسليم','Delivery'),day(),'date','required')}${area('technicalBrief',T('نطاق التكليف — دون مبالغ','Technical brief — no financial information'))}</div><div id="sourceEligibility" class="notice"></div>`,async v=>{const x=sources.find(x=>x.key===v.sourceKey);if(!x)throw Error(T('اختر المرجع','Choose source'));if(x.orderId||x.state==='closed'){await navigate('projects',x.projectId);return}if(x.state!=='ready')throw Error(x.reason);const pid=x.projectId||v.targetProject||null;const r=await execute('issue_order',pid,{sourceType:x.type,sourceId:x.id,pmId:v.pmId,checkerId:v.checkerId,externalOnly:!v.checkerId,deadline:v.deadline,technicalBrief:v.technicalBrief},lastActionId);await navigate('projects',r.projectId)},T('إصدار وحفظ أمر التشغيل','Issue and save order'));
 const f=$('editorForm');
 function update(){const x=sources.find(x=>x.key===f.elements.sourceKey.value),p=ws.projects.find(p=>p.id===x?.projectId);$('sourceEligibility').innerHTML=x?(p?projectMini(p)+'<br>':'')+E(x.reason):T('اختر مرجعًا معتمدًا.','Choose an approved source.');f.elements.technicalBrief.value=x?.scope?.filter(x=>!x.parentId).map(x=>x.label).join('\n')||'';
 const candidates=ws.projects.filter(p=>p.flex?.draft&&!p.operationalClosed&&(!p.flex.customerId||p.flex.customerId===x?.customerId));const select=f.elements.targetProject;
 select.innerHTML=x?.projectId?`<option value="${E(x.projectId)}">${E(x.projectId+' — '+x.projectName)}</option>`:`<option value="">${T('إنشاء مشروع جديد لهذا المرجع','Create new project for source')}</option>`+candidates.map(p=>`<option value="${E(p.id)}">${E(p.id+' — '+p.name)}</option>`).join('');
 select.disabled=!!x?.projectId;if(!x?.projectId&&candidates.some(p=>p.id===targetProject))select.value=targetProject;
 const target=ws.projects.find(p=>p.id===(x?.projectId||select.value));if(target){if(options(['Project Manager']).some(o=>o[0]===target.pm))f.elements.pmId.value=target.pm;if(target.checker)f.elements.checkerId.value=target.checker;if(target.deadline)f.elements.deadline.value=target.deadline;}
 $('editorSubmit').disabled=!!x&&!['ready','existing','closed'].includes(x.state);$('editorSubmit').textContent=x?.orderId||x?.state==='closed'?T('فتح الموجود','Open existing'):T('إصدار أمر التشغيل','Issue work order');
 }
 f.elements.targetProject.onchange=()=>{const p=ws.projects.find(x=>x.id===f.elements.targetProject.value);if(p){if(options(['Project Manager']).some(o=>o[0]===p.pm))f.elements.pmId.value=p.pm;if(p.checker)f.elements.checkerId.value=p.checker;if(p.deadline)f.elements.deadline.value=p.deadline;}};f.elements.sourceKey.onchange=update;update();
