function dataURL(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذر قراءة الملف'));r.readAsDataURL(f)})}
// R42.3.9.6: one visible employee upload path; selection is not a saved image.
async function prepareProjectPhoto396(file){
 if(!file)throw Error(T('اختر صورة من جهازك أولًا.','Choose a picture from your device first.'));
 if(!file.size||file.size>10*1024*1024)throw Error(T('اختر صورة حجمها لا يتجاوز 10 MB.','Choose an image no larger than 10 MB.'));
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)&&!(file.type===''&&/\.(png|jpe?g|webp)$/i.test(file.name)))throw Error(T('الصيغ المتاحة: PNG أو JPG أو WebP.','Choose a PNG, JPG or WebP image.'));
 const url=URL.createObjectURL(file),im=new Image();
 const encode=(c,type,quality)=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error(T('تعذر تجهيز الصورة. اختر صورة أخرى.','Could not prepare image. Choose another image.'))),type,quality));
 try{
  await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error(T('هذا الملف لا يفتح كصورة صحيحة. اختر صورة أخرى.','This file is not a readable image. Choose another image.')));im.src=url;});
  if(!im.naturalWidth||!im.naturalHeight||im.naturalWidth>10000||im.naturalHeight>10000||im.naturalWidth*im.naturalHeight>40e6)throw Error(T('أبعاد الصورة كبيرة جدًا. اختر لقطة أصغر.','Image dimensions are too large. Choose a smaller picture.'));
  let scale=Math.min(1,1600/im.naturalWidth,1600/im.naturalHeight),canvas=document.createElement('canvas'),blob;
  for(let attempt=0;attempt<5;attempt++){
   canvas.width=Math.max(1,Math.round(im.naturalWidth*scale));canvas.height=Math.max(1,Math.round(im.naturalHeight*scale));
   const ctx=canvas.getContext('2d');if(!ctx)throw Error(T('تعذر تجهيز معاينة الصورة.','Cannot create image preview.'));
   ctx.drawImage(im,0,0,canvas.width,canvas.height);blob=await encode(canvas,'image/webp',0.9);
   if(blob.size<=3*1024*1024)break;scale*=0.75;
  }
  if(blob.size>3*1024*1024)throw Error(T('الصورة كبيرة بعد التجهيز. اختر صورة أصغر.','Image remains too large. Choose a smaller image.'));
  const thumb=document.createElement('canvas'),z=Math.min(1,128/canvas.width,128/canvas.height);
  thumb.width=Math.max(1,Math.round(canvas.width*z));thumb.height=Math.max(1,Math.round(canvas.height*z));thumb.getContext('2d').drawImage(canvas,0,0,thumb.width,thumb.height);
  const thumbnail=await dataURL(await encode(thumb,'image/png'));
  return {src:await dataURL(blob),thumbnail,fileName:file.name,width:canvas.width,height:canvas.height,bytes:blob.size};
 }finally{URL.revokeObjectURL(url);}
}
