function passwordModal(){modal(T('تغيير كلمة المرور','Change password'),field('oldPassword',T('الحالية','Current'),'','password','required autocomplete="current-password"')+field('password',T('الجديدة','New'),'','password','required minlength="'+passwordMinimum+'" maxlength="128" autocomplete="new-password"'),async v=>{await api('/api/password',{method:'POST',body:JSON.stringify(v)});toast(T('تم تغيير كلمة المرور.','Password changed.'))})}
// Operational view helpers: display-only. No financial or workflow state is changed by rendering.
let taskFilter={state:'active',project:'',priority:'',search:'',engineer:''};
let focusedTask='',projectListState='active',projectListSearch='';
const personal=()=>['Engineer','Project Engineer'].includes(role());
const hoursText=v=>Number(v||0).toLocaleString('en-US',{maximumFractionDigits:2});
const priorityText=v=>T(...({Urgent:['عاجلة','Urgent'],High:['عالية','High'],Normal:['عادية','Normal'],Low:['منخفضة','Low']}[v]||[v||'عادية',v||'Normal']));
const priorityBadge=t=>`<span class="r392-priority ${E(t.priority||'Normal')}">${E(priorityText(t.priority))}</span>`;
const findProject=id=>ws.projects.find(p=>p.id===id)||ws.directory?.find(p=>p.id===id);
const historicalProject=p=>p.summary?.historical===true||p.historical===true||p.summary?.progressQuality==='legacy_unverified';
const trulyApproved=t=>t.approved===true||(t.approved===undefined&&t.status==='confirmed'&&Number(t.approvedProgress)===100);
const allTaskRows=()=>ws.projects.flatMap(p=>p.tasks.map(t=>({p,t})));
function permittedTaskRows(){return allTaskRows().filter(({p,t})=>!t.isSummary).filter(({p,t})=>owner()||role()==='Accountant'||role()==='Project Manager'&&myPM(p)||personal()&&assigned34(t,session.user.id)||role()==='Checker'&&(t.checker||p.checker)===session.user.id)}
function taskGroup({p,t}){if(p.operationalClosed||historicalProject(p))return 'history';if(trulyApproved(t))return 'approved';if(t.execution?.enabled&&personal()){const parts=t.execution.parts.filter(r=>(r.assignee||t.assignee)===session.user.id);if(parts.some(r=>r.status==='returned'))return 'returned';if(parts.some(r=>r.canEdit))return parts.every(r=>r.status==='todo')?'todo':'working';}if(t.status==='submitted')return 'submitted';if(t.status==='returned')return 'returned';if(t.status==='todo')return 'todo';return 'working'}
function rowOverdue({p,t}){return !p.operationalClosed&&!historicalProject(p)&&!trulyApproved(t)&&!!t.due&&t.due<day()}
function sortedTasks(rows){const rank={Urgent:0,High:1,Normal:2,Low:3};return rows.slice().sort((a,b)=>Number(b.t.status==='returned')-Number(a.t.status==='returned')||(rank[a.t.priority]??2)-(rank[b.t.priority]??2)||String(a.t.due||'9999').localeCompare(String(b.t.due||'9999'))||String(a.t.name).localeCompare(String(b.t.name)))}
function nextActionView(p){const a=p.nextAction;if(!a)return operationHint(p);return `<div class="r392-next"><span>${T('الخطوة التالية','Next action')}</span><b>${E(T(a.label,a.en))}</b><small>${a.actors?.length?T('على: ','Assigned to: ')+E(a.actors.map(name).join('، ')):''}</small>${a.code==='ack'&&myPM(p)?`<button class="primary" data-ack="${E(p.id)}|pm">${T('تأكيد الاستلام','Acknowledge receipt')}</button>`:''}${a.code==='assign'&&canPlan(p)?`<button data-plan="${E(p.id)}">${T('توزيع مهمة','Assign task')}</button>`:''}</div>`}
function teamView(p){const team=p.team||p.summary?.team||[];return `<div class="r392-project-team"><div><small>${T('مهندس المشروعات','Project manager')}</small><b>${E(name(p.pm))}</b></div><div><small>${T('مهندس / مهندسو التنفيذ','Assigned engineers')}</small><b>${team.length?E(team.map(x=>name(x.id)).join('، ')):`<span class="r392-unassigned">${T('لم يُعيّن مهندس تنفيذ بعد','No engineer assigned yet')}</span>`}</b></div><div><small>${T('المراجع','Checker')}</small><b>${E([...new Set([p.checker,...(p.tasks||[]).map(t=>t.checker)].filter(Boolean))].map(name).join('، ')||'—')}</b></div><div><small>${T('التسليم المخطط','Planned delivery')}</small><b class="ltr">${E(p.deadline||'—')}</b></div></div>`}
function operationMetrics(p){const s=p.summary;if(!s)return '';const tracking=owner()||myPM(p);return `<div class="r392-mini-stats"><div><small>${T('المهام','Tasks')}</small><b>${s.tasks}</b></div><div><small>${T('معتمد بالكامل','Fully approved')}</small><b>${s.approved}</b></div><div><small>${T('بانتظار المراجعة','Pending review')}</small><b>${s.submitted}</b></div><div><small>${T('مرتجع للتعديل','Returned')}</small><b>${s.returned}</b></div>${tracking?`<div><small>${T('متأخر','Overdue')}</small><b>${s.overdue}</b></div><div><small>${T('ساعات مخططة / فعلية','Planned / logged hours')}</small><b class="ltr">${s.plannedHours>0?hoursText(s.plannedHours):'—'} / ${hoursText(s.loggedHours)}</b></div>`:''}</div>${tracking?`<p class="muted r392-footnote">${T('ساعات المتابعة للقراءة فقط. التسجيل من قسم ساعات العمل.','Hours here are read-only. Enter time in Timesheets.')} ${s.unplanned?E(s.unplanned)+' '+T('مهمة دون تقدير ساعات؛ الصفر لا يعني أن التخطيط مكتمل.','task(s) have no estimate; zero is not a completed estimate.'):''}</p>`:''}`}
function taskActions(p,t,readOnly=false){const sub=t.submissions?.at(-1),actionable=!p.operationalClosed&&!p.finalTechnicalApproved&&!historicalProject(p);let html='';
 if(actionable&&!t.isSummary&&assigned34(t,session.user.id)&&personal()&&!['submitted','confirmed'].includes(t.status))html+=readOnly?`<button data-open-task="${E(p.id)}|${E(t.id)}">${T('فتح مهمتي','Open my task')}</button>`:`<button class="primary" data-update="${E(p.id)}|${E(t.id)}">${T('تحديث الإنجاز','Update progress')}</button><button data-submit-task="${E(p.id)}|${E(t.id)}">${T('إرسال للمراجع','Submit to checker')}</button>`;
 if(actionable&&!t.isSummary&&role()==='Checker'&&(t.checker||p.checker)===session.user.id&&t.status==='submitted'&&sub)html+=`<button class="primary" data-review="${E(p.id)}|${E(t.id)}">${T('مراجعة التقديم','Review submission')}</button>`;
 if(!t.isSummary&&!p.operationalClosed&&role()==='Checker'&&(t.checker||p.checker)===session.user.id&&['confirmed','submitted'].includes(t.status))html+=`<button data-reopen-task="${E(p.id)}|${E(t.id)}">${T('إعادة فتح موثقة','Reopen with reason')}</button>`;
 if(canPlan(p)&&!t.isSummary&&!['submitted','confirmed'].includes(t.status))html+=`<button data-edit-task="${E(p.id)}|${E(t.id)}">${T('تعديل التكليف','Edit assignment')}</button>`;
 if(actionable&&(owner()||myPM(p))&&t.assignee&&!trulyApproved(t))html+=`<button data-request-update="${E(p.id)}|${E(t.id)}">${T('طلب تحديث','Request update')}</button>`;
  if(canPlan(p)&&t.canBreakdown)html+=`<button data-breakdown="${E(p.id)}|${E(t.id)}">${T('تفصيل الحزمة إلى أعمال','Break down package')}</button>`;
  if(t.isSummary)html+=`<small class="muted">${T('حزمة ملخصة؛ حدّث الأعمال التابعة لها.','Summary package; update its deliverables.')}</small>`;
  else if(!actionable||['submitted','confirmed'].includes(t.status))html+=`<small class="muted">${T(p.operationalClosed?'مؤرشف للقراءة؛ لا تعديل صامت.':t.status==='submitted'?'تم الإرسال؛ بانتظار قرار المراجع.':'سجل معتمد / تاريخي. التعديل بإعادة فتح موثقة.','Read-only state; use documented review/reopen workflow.')}</small>`;
  return html+`<button data-history="${E(p.id)}|${E(t.id)}">${T('السجل','History')}</button>`;
}
function taskView(review=false){const rows=permittedTaskRows(),states=[['active',T('مطلوب مني','Needs action')],['todo',T('لم يبدأ','Not started')],['working',T('قيد التنفيذ','Working')],['returned',T('مرتجع','Returned')],['submitted',T('بانتظار المراجعة','Pending review')],['approved',T('معتمد','Approved')],['all',T('كل التكليفات النشطة','All current assignments')],['history',T('السجل / الأرشيف','History / archive')]];

 const count=k=>rows.filter(x=>k==='all'?taskGroup(x)!=='history':k==='active'?['todo','working','returned'].includes(taskGroup(x)):taskGroup(x)===k).length;
 const selectedProjects=[...new Map(rows.map(x=>[x.p.id,x.p])).values()];
 return head(review?'review':'tasks',T('المهمة هي مكان تحديث المنجز والمتبقي وإرسال العمل للمراجع. الساعات في قسمها المستقل.','Update completed/remaining work and submit here. Time entry is in Timesheets.'),`<button data-refresh>${T('تحديث','Refresh')}</button>`)+
 `<div class="r392-task-tabs" role="group" aria-label="${T('حالات المهام','Task states')}">${states.map(([k,l])=>`<button data-task-filter="${k}" class="${taskFilter.state===k?'selected':''}">${l}<b>${count(k)}</b></button>`).join('')}</div><div class="filterbar r392-filters"><input id="taskSearch" value="${E(taskFilter.search)}" placeholder="${T('ابحث بالمشروع أو المهمة أو ملاحظتها','Search project, task or note')}"><select id="taskProject"><option value="">${T('كل المشاريع','All projects')}</option>${selectedProjects.map(p=>`<option value="${E(p.id)}" ${taskFilter.project===p.id?'selected':''}>${E(p.id+' — '+p.name)}</option>`).join('')}</select><select id="taskPriority"><option value="">${T('كل الأولويات','All priorities')}</option>${['Urgent','High','Normal','Low'].map(k=>`<option value="${k}" ${taskFilter.priority===k?'selected':''}>${priorityText(k)}</option>`).join('')}</select></div><div id="taskRows">${filteredTaskTable(rows)}</div>`;
}
function filteredTaskTable(rows=permittedTaskRows()){const f=taskFilter;return taskTable(rows.filter(x=>{
 const g=taskGroup(x);return (f.state==='all'?g!=='history':f.state==='active'?['todo','working','returned'].includes(g):g===f.state)&&(!f.project||x.p.id===f.project)&&(!f.priority||x.t.priority===f.priority)&&(!f.search||[x.p.id,x.p.name,x.t.name,x.t.assignmentNotes,x.t.completedNote,x.t.remainingNote].join(' ').toLowerCase().includes(f.search.toLowerCase()));
 }))}
function requestUpdateModal(pid,tid){const {p,t}=get(pid,tid);modal(T('طلب تحديث من المهندس','Request engineer update'),`<div class="notice">${projectMini(p)}<br>${E(t.name)} — ${E(name(t.assignee))}</div>${area('note',T('المطلوب من المهندس','Request to engineer'),T('يرجى تحديث المنجز والمتبقي والموعد المتوقع.','Please update completed / remaining work and expected finish.'),'required')}`,v=>execute('task_request_update',pid,{taskId:tid,note:v.note},lastActionId),T('إرسال الطلب','Send request'))}
function directoryDetail(p){return head('projects',T('نظرة تشغيلية عامة — للاطلاع فقط. المهام المخصصة لك تظهر في «مهامي».','Read-only portfolio view. Your own assignments appear in My Tasks.'),`<button data-route-inline="projects">${T('كل المشاريع','All projects')}</button>`)+`<article class="card"><div class="project-head">${projectMini(p,'project-mini-detail')}<span class="tag">${T('للاطلاع فقط','Read only')}</span></div>${teamView(p)}${progress(p)}${nextActionView(p)}${operationMetrics(p)}</article>`}
function currentProjectList(){const map=new Map((ws.directory||[]).map(p=>[p.id,p]));ws.projects.forEach(p=>map.set(p.id,{...map.get(p.id),...p,canOpen:true}));return [...map.values()]}
function projectCardsHTML(){return currentProjectList().filter(p=>(!projectListSearch||[p.id,p.name].join(' ').toLowerCase().includes(projectListSearch.toLowerCase()))&&(projectListState==='all'||projectListState==='active'&&!p.operationalClosed||projectListState==='archived'&&p.operationalClosed||projectListState==='draft'&&p.flex?.draft&&!p.operationalClosed)).sort((a,b)=>Number(a.operationalClosed)-Number(b.operationalClosed)||String(a.deadline||'9999').localeCompare(String(b.deadline||'9999'))).map(p=>owner()&&p.tasks?ownerProjectCard(p):projectCard(p)).join('')||`<div class="empty">${T('لا توجد مشاريع ضمن التصفية. راجع المؤرشف للبيانات السابقة، أو أضف مشروعًا جديدًا.','No projects match this filter; use Archive to view preserved records.')}</div>`}
function workloadView(projects){const rows=projects.flatMap(p=>p.tasks.map(t=>({p,t}))),ids=[...new Set(rows.map(x=>x.t.assignee).filter(Boolean))];if(!ids.length)return `<div class="empty compact">${T('لا يوجد تسكين بعد؛ لن تُخترع أسماء مهندسين.','No assignments yet; engineers will not be invented.')}</div>`;return `<div class="table-wrap"><table class="r392-workload"><thead><tr><th>${T('المهندس','Engineer')}</th><th>${T('المهام الجارية','Open tasks')}</th><th>${T('متأخر','Late')}</th><th>${T('عند المراجع','At checker')}</th><th>${T('معتمد','Approved')}</th><th>${T('مخطط / فعلي (ساعة)','Planned / logged (h)')}</th></tr></thead><tbody>${ids.map(id=>{const r=rows.filter(x=>x.t.assignee===id);return `<tr><td><b>${E(name(id))}</b></td><td>${r.filter(x=>!trulyApproved(x.t)).length}</td><td>${r.filter(rowOverdue).length}</td><td>${r.filter(x=>x.t.status==='submitted').length}</td><td>${r.filter(x=>trulyApproved(x.t)).length}</td><td class="ltr">${hoursText(r.reduce((s,x)=>s+Number(x.t.plannedHours||0),0))} / ${hoursText(r.reduce((s,x)=>s+Number(x.t.hours?.logged||0),0))}</td></tr>`}).join('')}</tbody></table></div>`}
function notificationOpen(n){if(n.agreementId){supplierFilter29=n.projectId||'';navigate('awards');return;}if(n.followupId){flowFocus3922=n.followupId;flowFilter3922='all';flowProject3922='';flowPerson3922='';}const fallback=n.projectId?'projects':'notifications';let target=n.targetRoute||fallback;if(n.taskId&&!menus().includes(target))target='projects';if(!menus().includes(target))target=fallback;if(!menus().includes(target))return;taskFilter={state:'all',project:n.projectId||'',priority:'',search:'',engineer:''};focusedTask=n.taskId||'';const p=findProject(n.projectId);if(p?.operationalClosed||historicalProject(p||{}))taskFilter.state='history';navigate(target,n.projectId,focusedTask)}

Object.assign(events,{execution_board_enable:'فتح لوحة نسب الأجزاء',execution_parts_save:'حفظ نسب الأجزاء',execution_parts_submit:'إرسال أجزاء للمراجع',execution_parts_review:'مراجعة نسب الأجزاء',execution_part_reopen:'إعادة فتح جزء موثقة',time_activity_add:'إضافة نشاط فرعي',task_breakdown:'تفصيل وتوزيع الحزمة',timesheet_review:'قرار اعتماد الساعات',timesheet_edit:'تصحيح وإعادة تقديم ساعات',timesheet_reopen:'إرجاع ساعات للتصحيح',cost_rate_set:'تثبيت سعر تكلفة بتاريخ',record_manage:'إدارة إزالة أو استرجاع سجل',timesheet_price:'تثبيت أو تصحيح تكلفة الوقت'});
