function engineerDeskView397(forcedProject='', forcedTask='') {
  if (deskChoice397.user !== session.user.id) {
    deskChoice397 = {user:session.user.id,project:'',task:'',mode:'active'};
    pendingDeskRequest397 = null;
  }
  const rows = permittedTaskRows().filter(({t})=>!t.isSummary);
  const historical = ({p})=>p.operationalClosed||historicalProject(p);
  if (forcedProject) {
    const row=rows.find(x=>x.p.id===forcedProject && (!forcedTask||x.t.id===forcedTask));
    if(row){deskChoice397.project=forcedProject;deskChoice397.mode=historical(row)?'history':'active';}
  }
  if(forcedTask)deskChoice397.task=forcedTask;
  const candidates=sortedTasks(rows.filter(row=>deskChoice397.mode==='history'?historical(row):!historical(row)));
  const projects=[...new Map(candidates.map(({p})=>[p.id,p])).values()];
  let p=projects.find(x=>x.id===deskChoice397.project)||projects[0];
  const tasks=candidates.filter(x=>x.p.id===p?.id).map(x=>x.t);
  let t=tasks.find(x=>x.id===deskChoice397.task)||tasks.find(x=>x.execution?.parts?.some(r=>r.canEdit))||tasks.find(x=>!['confirmed','submitted'].includes(x.status))||tasks[0];
  deskChoice397.project=p?.id||'';deskChoice397.task=t?.id||'';
  return engineerUI397.render({T,E,name,p,t,projects,tasks,mode:deskChoice397.mode,user:session.user,timestamp,photoAction:photoAction395,priorityText,deliveryPanel:completionPanel3910});
}
